export function hasScene(name?: string, exercise?: string): boolean {
  return Boolean(name && exercise && SCENES[name]?.[exercise]);
}

export default function Character({
  name,
  exercise,
  size = 260,
  animated = true,
}: {
  name?: string;
  exercise?: string;
  size?: number;
  animated?: boolean;
}) {
  if (!name) return null;
  const inner = (exercise && SCENES[name]?.[exercise]) || IDLE[name];
  if (!inner) return null;
  return (
    <svg
      className={animated ? "pz-char" : "pz-char pz-still"}
      width={size}
      height={Math.round((size * 200) / 240)}
      viewBox="0 0 240 200"
      role="img"
      aria-label={exercise ? `${exercise} 하는 ${name}` : `${name} 캐릭터`}
      dangerouslySetInnerHTML={{ __html: inner }}
    />
  );
}
